package emtmodern.energy;
import net.minecraftforge.common.ForgeConfigSpec;
public class EmtEnergyConfig {
    public static final ForgeConfigSpec SPEC;
    public static final java.util.List<ForgeConfigSpec.DoubleValue> SOLAR_OUTPUT;
    public static final java.util.Map<String,ForgeConfigSpec.DoubleValue> PRIMAL_OUTPUT=new java.util.LinkedHashMap<>();
    public static final ForgeConfigSpec.DoubleValue OUTPUT_CAP;
    public static final ForgeConfigSpec.BooleanValue ENCHANTING,NIGHT_VISION_OFF,RAIN_IMPACT;
    public static final ForgeConfigSpec.DoubleValue NANO_SPEED,QUANTUM_SPEED,NANO_JUMP,QUANTUM_JUMP;
    static {var builder=new ForgeConfigSpec.Builder();builder.push("generation");SOLAR_OUTPUT=java.util.List.of(
        builder.comment("压缩太阳能发电量，EU/t", "设置说明 / Setting: Compressed solar output in EU/t", "初始值 / Default: " + String.valueOf(10.0) + "; 范围 / Range: " + String.valueOf(0) + ".." + String.valueOf(Double.MAX_VALUE), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("compressed_solar_output",10.0,0,Double.MAX_VALUE),
        builder.comment("双重压缩太阳能发电量，EU/t", "设置说明 / Setting: Double compressed solar output in EU/t", "初始值 / Default: " + String.valueOf(100.0) + "; 范围 / Range: " + String.valueOf(0) + ".." + String.valueOf(Double.MAX_VALUE), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("double_compressed_solar_output",100.0,0,Double.MAX_VALUE),
        builder.comment("三重压缩太阳能发电量，EU/t", "设置说明 / Setting: Triple compressed solar output in EU/t", "初始值 / Default: " + String.valueOf(1000.0) + "; 范围 / Range: " + String.valueOf(0) + ".." + String.valueOf(Double.MAX_VALUE), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("triple_compressed_solar_output",1000.0,0,Double.MAX_VALUE));builder.pop();builder.push("essentia");
        var defaults=java.util.Map.of("aer",15000d,"aqua",5000d,"ignis",20000d,"ordo",16000d,"perditio",10000d,"terra",2000d);
        defaults.forEach((tag,value)->PRIMAL_OUTPUT.put(tag,builder.comment("每点 "+tag+" 源质的发电量 EU；初始 "+value+"，范围 0..Double.MAX_VALUE；重启世界。", "EU per point of "+tag+" essentia; default "+value+", range 0..Double.MAX_VALUE; restart the world.").defineInRange(tag,value,0,Double.MAX_VALUE)));
        OUTPUT_CAP=builder.comment("每点复合源质发电量上限，EU；-1 不限", "设置说明 / Setting: EU cap per compound essentia point; -1 is unlimited", "初始值 / Default: " + String.valueOf(-1.0) + "; 范围 / Range: " + String.valueOf(-1) + ".." + String.valueOf(Double.MAX_VALUE), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("output_cap",-1.0,-1,Double.MAX_VALUE);builder.pop();builder.push("equipment");ENCHANTING=builder.comment("允许电力装备接受附魔", "设置说明 / Setting: Allow enchantments on electric equipment", "初始值 / Default: " + String.valueOf(false) + "; 可选 / Allowed: true, false", "修改后重启世界或服务器 / Restart the world/server after editing.").define("enchanting",false);NIGHT_VISION_OFF=builder.comment("禁用电力护目镜的夜视", "设置说明 / Setting: Disable electric goggles night vision", "初始值 / Default: " + String.valueOf(false) + "; 可选 / Allowed: true, false", "修改后重启世界或服务器 / Restart the world/server after editing.").define("night_vision_off",false);
        RAIN_IMPACT=builder.comment("雨天影响飞翼的推进效果", "设置说明 / Setting: Rain affects wing propulsion", "初始值 / Default: " + String.valueOf(true) + "; 可选 / Allowed: true, false", "修改后重启世界或服务器 / Restart the world/server after editing.").define("impact_of_rain",true);NANO_SPEED=builder.comment("纳米旅行者之靴的额外移动速度", "设置说明 / Setting: Nano Traveller Boots movement speed bonus", "初始值 / Default: " + String.valueOf(.25) + "; 范围 / Range: " + String.valueOf(0) + ".." + String.valueOf(10), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("nano_boots_speed",.25,0,10);QUANTUM_SPEED=builder.comment("量子旅行者之靴的额外移动速度", "设置说明 / Setting: Quantum Traveller Boots movement speed bonus", "初始值 / Default: " + String.valueOf(.5) + "; 范围 / Range: " + String.valueOf(0) + ".." + String.valueOf(10), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("quantum_boots_speed",.5,0,10);NANO_JUMP=builder.comment("纳米旅行者之靴的跳跃增量", "设置说明 / Setting: Nano Traveller Boots jump bonus", "初始值 / Default: " + String.valueOf(.6) + "; 范围 / Range: " + String.valueOf(0) + ".." + String.valueOf(10), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("nano_boots_jump",.6,0,10);QUANTUM_JUMP=builder.comment("量子旅行者之靴的跳跃增量", "设置说明 / Setting: Quantum Traveller Boots jump bonus", "初始值 / Default: " + String.valueOf(.9) + "; 范围 / Range: " + String.valueOf(0) + ".." + String.valueOf(10), "修改后重启世界或服务器 / Restart the world/server after editing.").defineInRange("quantum_boots_jump",.9,0,10);builder.pop();SPEC=builder.build();}
    public static double output(int compression){return SOLAR_OUTPUT.get(compression).get();}
    public static double essentiaOutput(tc4revival.aspect.Aspect aspect){
        return tc4revival.aspect.TCAspects.catalog().weightedFold(aspect,
            tag->PRIMAL_OUTPUT.containsKey(tag)?PRIMAL_OUTPUT.get(tag).get():0,OUTPUT_CAP.get());
    }
}
